[96873] = {"Un dolor de cuello", {"Pa'zula, en el Poblado Sen'jin, quiere que recojas 3 residuos luminosos. Se pueden obtener residuos luminosos al desencantar los colgantes embrujados que arrojan los trols de las Islas del Eco."}},
[96874] = {"Un hacha espinosa", {"Ug'thok, en Orgrimmar, quiere que consigas 5 espinas deterioradas de las bestias del Monte del Trueno y 5 piedras de pulir férreas."}},
[96875] = {"Las bestias de Monte del Trueno", {"Kamari, en Orgrimmar, quiere que consigas 5 pellejos de lagarto duros de las bestias de Monte del Trueno y 2 pellejos ligeros curtidos."}},
[96876] = {"La mochila perdida de Ukor", {"Devuélvele la mochila a Ukor en el sur de Durotar."}},
[96877] = {"Pezuña de Halikor", {"Lleva la pezuña de Halikor a Orgrimmar."}},
