[96896] = {"Una causa justa", {"Escucha la conversación entre Danitha Morr y Leonid Barthalomew el Venerado."}},
[96897] = {"El Culto de los Malditos", {"Mata a 8 neófitos oscuros y 8 déspotas oscuros en Claros de Tirisfal."}},
[96898] = {"Los restos de la guerra", {"Recoge 12 trozos de cristal necrótico en Claros de Tirisfal."}},
