[97220] = {"Favor de Philmor", {"Lleva el cargamento de entrada a la puerta del almacén que se encuentra en la tienda de Queso de Trias del Distrito de Mercaderes."}},
[97222] = {"Víveres de entrada", {"Lleva el cargamento de entrada por las escaleras de la tienda de Trias y déjalo delante de la puerta."}},
