[97242] = {"La mezcla de Yelmak", {"Recoge algunos esquejes de eneas y césped lanza que crecen alrededor de las corrientes de agua en el Valle del Honor, y regresa a Kor'geld en Alquimia y Pociones de Yelmak."}},
[97243] = {"El llamado del fuego", {"Lleva la antorcha de la Llama Latente a Olariaan Fuegoveloz en el Santuario de las Llamas, en los Bajíos Ventobaya."}},
[97244] = {"El llamado del fuego", {"Mata al sacerdocielo Faladiel en los Bajíos Ventobaya y recoge su corazón."}},
[97245] = {"El llamado del fuego", {"Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota al espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Fuegoveloz en los Bajíos Ventobaya, cuando hayas salido victorioso."}},
[97246] = {"Comida apetecible", {"Visita la fosa de lava de Borstan y dile que Thatog quiere que entregues el almuerzo de Migi personalmente."}},
[97249] = {"Comida favorita", {"Llévale el almuerzo a Migi detrás del Fuerte Grommash."}},
[97250] = {"Falsa acusación, justa redención", {"Mata a los soldados de la Alianza que están usurpando Los Baldíos en la frontera de Marjal Revolcafango. Luego, regresa con Bruto Logmar en el Campamento Taurajo."}},
[97253] = {"Partes y piezas", {"Recoge 5 puñados de piezas complicadas en la zona superior del campamento pirata ubicado al sur de Trinquete. Luego, regresa con Desdio el Desdichado en Trinquete."}},
[97257] = {"El llamado del fuego", {"Espera a que Olariaan comience el ritual en el blandón de ofrenda y sigue sus instrucciones.","","Debes llevar la llama eterna a Valanaar antes de que se acabe el tiempo."}},
